(()=>{const section=document.createElement('section');section.className='editor';section.id='backups';section.innerHTML='<h2>Backups</h2><p>Back up questions, accounts, saved notes, collections, feedback, images and app files. Legacy browser-only data is excluded until imported.</p><button type="button" class="primary" id="backup-now">Back up now</button><p id="backup-status" role="status"></p>';document.body.append(section);const status=document.getElementById('backup-status'),button=document.getElementById('backup-now');function show(x){status.textContent=x.created?'Last verified backup: '+new Date(x.created).toLocaleString()+' · '+x.questions+' questions. Saved to '+x.archive:'No backup has been recorded yet.'}fetch('/api/backup-status').then(r=>{if(!r.ok)throw Error();return r.json()}).then(show).catch(()=>status.textContent='Could not load backup status.');button.onclick=async()=>{button.disabled=true;status.textContent='Creating and checking backup…';try{const r=await fetch('/api/backup',{method:'POST',headers:{'Content-Type':'application/json','X-Quiz-Admin':'1'},body:'{}'});const x=await r.json();if(!r.ok)throw Error(x.error||'Backup failed.');show(x)}catch(e){status.textContent=e.message}finally{button.disabled=false}}})();
